export function lifeStory(scores,index,language='en'){const score=scores?.[index];if(!Number.isFinite(score)||score<0||score>100||!Number.isInteger(index)||index<0||index>4)throw new Error('Invalid story.');const row=(language==='hi'?hindi:english)[index][band(score)];return{daily:row[0],relationships:row[1],pressure:row[2],need:row[3]}}
export function scorePosition(score,language='en'){if(!Number.isFinite(score)||score<0||score>100)throw new Error('Invalid score.');const distance=Math.abs(score-50),level=distance<=10?0:distance<=25?1:2;return{band:band(score),distance,level,label:(language==='hi'?['दोनों ओर की पसंद','हल्का झुकाव','ज़्यादा स्पष्ट झुकाव']:['A mix of both','A gentle lean','A more pronounced lean'])[level]}}
export function profileHighlights(scores){if(!Array.isArray(scores)||scores.length!==5||Array.from(scores).some(s=>!Number.isFinite(s)||s<0||s>100))throw new Error('Invalid scores.');const ranked=scores.map((score,index)=>({index,score,distance:Math.abs(score-50)})).sort((a,b)=>b.distance-a.distance||a.index-b.index);const closest=[...ranked].sort((a,b)=>a.distance-b.distance||a.index-b.index),mixed=closest.find(item=>item.distance===closest[0].distance&&item.index!==ranked[0].index)||closest[0];return{pronounced:ranked[0],mixed,allMixed:ranked[0].distance<=10}}
export function responseEvidence(report,index){if(report?.version!==VERSION||!Array.isArray(report.responses)||report.responses.length!==QUESTION_COUNT||Array.from(report.responses).some(a=>!Number.isInteger(a)||a<0||a>4))return null;const scores=scoreAnswers(report.responses);if(!Array.isArray(report.scores)||scores.some((score,i)=>score!==report.scores[i]))return null;return questions.flatMap((q,i)=>q.dim===index?[{number:i+1,text:q.text,answer:report.responses[i],label:agreement[report.responses[i]],scored:q.reverse?4-report.responses[i]:report.responses[i],reverse:q.reverse===true}]:[])}
